1	import type { FastifyInstance } from 'fastify'
2	import { claudeClient } from '../services/claudeClient'
3	import type { ProfileAnswers } from '../types'
4	
5	export async function personaRoute(app: FastifyInstance) {
6	  app.post<{ Body: ProfileAnswers }>('/api/persona', async (request, reply) => {
7	    const { name, situation, city, concern, language } = request.body
8	
9	    if (!name || !situation || !city || !concern || !language) {
10	      return reply.status(400).send({ error: 'All fields required' })
11	    }
12	
13	    const response = await claudeClient.messages.create({
14	      model: 'claude-sonnet-4-6',
15	      max_tokens: 256,
16	      messages: [
17	        {
18	          role: 'user',
19	          content: `Write a 2–3 sentence factual persona summary for a person with these details:
20	Name: ${name}
21	Situation: ${situation}
22	City: ${city}
23	Main concern: ${concern}
24	Preferred language: ${language}
25	
26	Be factual and concise. No assumptions beyond what is given. Output only the summary text.`,
27	        },
28	      ],
29	    })
30	
31	    const text = response.content.find((b) => b.type === 'text')
32	    const persona = text?.type === 'text' ? text.text : ''
33	
34	    return { persona }
35	  })
36	}
